"""Generate fixtures."""

import os
import json
import numpy as np

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)

PHI = (1.0 + np.sqrt(5.0)) / 2.0
SQRT_5 = np.sqrt(5.0)


def ref(x64):
    """Evaluate Binet's formula in double precision.

    # Arguments

    * `x64::ndarray`: input values (float64)

    # Examples

    ``` python
    python> ref(np.array([2.0]))
    array([1.0])
    ```
    """
    term1 = np.power(PHI, x64)
    term2 = np.cos(np.pi * x64) / term1
    return (term1 - term2) / SQRT_5, term1, term2


def gen(x, name):
    """Generate fixture data and write to file.

    # Arguments

    * `x`: domain
    * `name::str`: output filename

    # Examples

    ``` python
    python> x = linspace(0.5, 5.0, 500)
    python> gen(x, './small_positive.json')
    ```
    """
    # Round the inputs to single precision first, and evaluate the reference at
    # the rounded values, so that fixtures match the tested domain:
    x = np.asarray(x, dtype=np.float32)
    x64 = x.astype(np.float64)
    y, term1, term2 = ref(x64)

    # Drop points where the two terms of Binet's formula nearly cancel, as ULP
    # comparison is meaningless there. Cancellation requires
    # `|cos(pi*x)| ~= phi^(2*x)`, which is only reachable when `|x|` is small
    # enough for the single-precision spacing of `x` to resolve small values of
    # `|cos(pi*x)|`; for `|x| >= 40`, no sampled point can cancel.
    magnitude = np.abs(term1) + np.abs(term2)
    ratio = np.abs(y) * SQRT_5 / magnitude
    mask = ~((np.abs(x64) < 40.0) & (ratio < 0.05))

    data = {
        "x": x[mask].tolist(),
        "expected": y[mask].tolist()
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(DIR, name)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w", encoding="utf-8") as outfile:
        json.dump(data, outfile)
        outfile.write("\n")


def main():
    """Generate fixture data."""
    # Small positive values:
    x = np.linspace(0.5, 5.0, 500)
    gen(x, "small_positive.json")

    # Medium positive values:
    x = np.linspace(5.0, 50.0, 500)
    gen(x, "medium_positive.json")

    # Large positive values (below the overflow threshold):
    x = np.linspace(50.0, 184.3, 500)
    gen(x, "large_positive.json")

    # Small negative values:
    x = np.linspace(-5.0, -0.5, 500)
    gen(x, "small_negative.json")

    # Medium negative values:
    x = np.linspace(-50.0, -5.0, 500)
    gen(x, "medium_negative.json")

    # Large negative values (below the overflow threshold):
    x = np.linspace(-184.3, -50.0, 500)
    gen(x, "large_negative.json")

    # Values beyond the overflow threshold of `phi^x`, both signs; the results
    # are still finite, as the dominant term is evaluated in log space:
    x = np.concatenate([
        np.linspace(184.4, 186.0, 250),
        -np.linspace(184.4, 186.0, 250)
    ])
    gen(x, "tail.json")


if __name__ == "__main__":
    main()
